/** Apple catalog references only. These values never grant soundtrack rights. */
export type AppleMusicTrack = {
  id: string;
  storefront: string;
  title: string;
  artist: string;
  album: string;
  artworkUrl: string | null;
  url: string;
  explicit: boolean;
};

export function parseAppleMusicLink(value: string): { id: string; storefront: string; url: string } | null {
  try {
    const url = new URL(value.trim());
    if (url.protocol !== 'https:' || url.hostname !== 'music.apple.com' || url.port || url.username || url.password) return null;
    const parts = url.pathname.split('/').filter(Boolean);
    if (!/^[a-z]{2}$/i.test(parts[0] || '') || !['song', 'album'].includes(parts[1])) return null;
    const id = parts[1] === 'album' ? url.searchParams.get('i') : parts.at(-1);
    if (!id || !/^\d{1,24}$/.test(id)) return null;
    const storefront = parts[0].toLowerCase();
    return { id, storefront, url: `https://music.apple.com/${storefront}/song/${id}` };
  } catch { return null; }
}

export function appleMusicShareText(track: AppleMusicTrack): string {
  return `${[track.title, track.artist].filter(Boolean).join(' · ')}\n${track.url}`;
}

/** Discard arbitrary URLs and every playback/download field from provider data. */
export function appleMusicTrackFromCatalog(value: unknown, storefront: string): AppleMusicTrack | null {
  if (!value || typeof value !== 'object' || !/^[a-z]{2}$/.test(storefront)) return null;
  const row = value as Record<string, unknown>;
  const attrs = row.attributes as Record<string, unknown> | undefined;
  const id = typeof row.id === 'string' ? row.id : '';
  if (row.type !== 'songs' || !/^\d{1,24}$/.test(id) || !attrs || typeof attrs.name !== 'string' || typeof attrs.artistName !== 'string') return null;
  let artworkUrl: string | null = null;
  const artwork = attrs.artwork as { url?: unknown } | undefined;
  if (typeof artwork?.url === 'string') {
    try {
      const url = new URL(artwork.url.replace('{w}', '300').replace('{h}', '300'));
      if (url.protocol === 'https:' && url.hostname.endsWith('.mzstatic.com') && !url.username && !url.password && !url.port) artworkUrl = url.toString();
    } catch { /* A track is usable without its artwork. */ }
  }
  return {
    id, storefront, title: attrs.name.slice(0, 300), artist: attrs.artistName.slice(0, 300),
    album: typeof attrs.albumName === 'string' ? attrs.albumName.slice(0, 300) : '',
    artworkUrl, url: `https://music.apple.com/${storefront}/song/${id}`,
    explicit: attrs.contentRating === 'explicit',
  };
}

// One bounded network operation, including response-body consumption. Preserve
// both the caller cancellation and any timeout/signal supplied by the SDK.
export function boundedFetch(fetcher: typeof fetch, parent?: AbortSignal, deadlineMs = 8000): typeof fetch {
  return (input, init) => {
    const signals: AbortSignal[] = [AbortSignal.timeout(deadlineMs)];
    if (parent) signals.push(parent);
    const initSignal = (init as { signal?: AbortSignal | null } | undefined)?.signal;
    if (initSignal) signals.push(initSignal);
    if (input instanceof Request) signals.push(input.signal);
    return fetcher(input, { ...init, signal: AbortSignal.any(signals) });
  };
}

type Caller = { rpc(name: string, args: Record<string, unknown>): PromiseLike<{ data: unknown; error: unknown }> };

// Invoke with the verified caller's Authorization header, never a service key.
// This reaches the authoritative Auth/session/member/device checks even when
// the protected handler subsequently uses a service client or external API.
export async function businessSessionAllowed(caller: Caller): Promise<boolean> {
  try { const {data,error}=await caller.rpc('business_session_allowed',{});return !error&&data===true; }
  catch { return false; }
}
export function guardBusinessRequest(
  handler: (request: Request) => Response | Promise<Response>,
  client: (request: Request) => Caller,
  shouldCheck: (request: Request) => boolean = request => request.method !== 'OPTIONS',
) {
  return async (request: Request): Promise<Response> => {
    if (shouldCheck(request) && !await businessSessionAllowed(client(request))) {
      return new Response(JSON.stringify({error:'Sign in again to continue.',code:'ACTIVE_SESSION_REQUIRED'}),{
        status:401,headers:{'Content-Type':'application/json','Cache-Control':'private, no-store, max-age=0',
          'CDN-Cache-Control':'no-store','Access-Control-Allow-Origin':'*','Access-Control-Allow-Headers':'authorization,apikey,x-client-info,content-type,range',
          'Access-Control-Allow-Methods':'POST,GET,HEAD,OPTIONS'},
      });
    }
    return handler(request);
  };
}

import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { guardBusinessRequest } from './businessSessionGuard.ts';
import { boundedFetch } from './boundedFetch.ts';

export function serveBusinessRequest(handler: (request: Request) => Response | Promise<Response>, shouldCheck?: (request: Request) => boolean) {
  Deno.serve(guardBusinessRequest(handler, request => createClient(
    Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_ANON_KEY')!,{
      auth:{persistSession:false,autoRefreshToken:false},
      global:{headers:{Authorization:request.headers.get('Authorization')||''},fetch:boundedFetch(fetch,request.signal)},
    },
  ),shouldCheck));
}

import { appleMusicTrackFromCatalog } from '../../../shared/appleMusic.ts';
import { signMusicDeveloperToken, type MusicCredentials } from './token.ts';

type Dependencies = {
  env: (name: string) => string | undefined;
  authenticate: (request: Request) => Promise<{ id: string; anonymous?: boolean } | null>;
  fetch?: typeof fetch;
  sign?: typeof signMusicDeveloperToken;
  now?: () => number;
};

export function createAppleMusicHandler(deps: Dependencies) {
  const requestTimes = new Map<string, number[]>();
  return async (request: Request): Promise<Response> => {
    const origin = request.headers.get('origin');
    const allowedOrigins = (deps.env('APPLE_MUSIC_ALLOWED_ORIGINS') || '').split(',').map(x => x.trim()).filter(value => {
      try { const url = new URL(value); return url.protocol === 'https:' && url.origin === value; } catch { return false; }
    });
    const originAllowed = !origin || allowedOrigins.includes(origin);
    const headers: Record<string, string> = {
      'Content-Type': 'application/json', 'Cache-Control': 'no-store', Vary: 'Origin',
      'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info',
      'Access-Control-Allow-Methods': 'POST, OPTIONS',
      ...(origin && originAllowed ? { 'Access-Control-Allow-Origin': origin } : {}),
    };
    const json = (status: number, data: unknown) => new Response(JSON.stringify(data), { status, headers });
    if (!originAllowed) return json(403, { code: 'ORIGIN_NOT_ALLOWED', error: 'Apple Music is not available from this address.' });
    if (request.method === 'OPTIONS') return new Response(null, { status: 204, headers });
    if (request.method !== 'POST') return json(405, { error: 'Use POST.' });
    if (Number(request.headers.get('content-length')) > 4096) return json(413, { error: 'Request is too large.' });
    try {
      const user = await deps.authenticate(request);
      if (!user || user.anonymous) return json(401, { code: 'SIGN_IN_REQUIRED', error: 'Sign in to search Apple Music.' });
      const now = deps.now?.() ?? Date.now();
      // Bound isolate memory as well as request bursts. Provider limits remain authoritative.
      if (requestTimes.size > 2000) for (const [id, hits] of requestTimes) if (hits.at(-1)! < now - 60000) requestTimes.delete(id);
      if (requestTimes.size > 4000) return json(429, { error: 'Music search is busy. Try again shortly.' });
      const hits = (requestTimes.get(user.id) || []).filter(t => t > now - 60000);
      if (hits.length >= 30) return json(429, { error: 'Please wait a minute before searching again.' });
      requestTimes.set(user.id, [...hits, now]);
      const raw = await request.text();
      if (raw.length > 4096) return json(413, { error: 'Request is too large.' });
      let body: Record<string, unknown>;
      try { body = JSON.parse(raw); } catch { return json(400, { error: 'Invalid request.' }); }
      if (!body || typeof body !== 'object' || Array.isArray(body)) return json(400, { error: 'Invalid request.' });
      const teamId = deps.env('APPLE_MUSIC_TEAM_ID') || '';
      const keyId = deps.env('APPLE_MUSIC_KEY_ID') || '';
      const privateKey = deps.env('APPLE_MUSIC_PRIVATE_KEY') || '';
      const configured = /^[A-Z0-9]{10}$/.test(teamId) && /^[A-Z0-9]{10}$/.test(keyId) && privateKey.includes('PRIVATE KEY');
      if (body.action === 'status') return json(200, { configured, playbackAvailable: configured && !!origin, soundtrackAvailable: false });
      if (!configured) return json(503, { code: 'MUSIC_NOT_CONFIGURED', error: 'Apple Music search is not available yet. You can still share an Apple Music song link.' });
      const credentials: MusicCredentials = { teamId, keyId, privateKey };
      const sign = deps.sign || signMusicDeveloperToken;
      if (body.action === 'token') {
        if (!origin) return json(400, { error: 'Web playback requires an approved web origin.' });
        return json(200, await sign(credentials, origin, now));
      }
      if (!['search', 'track'].includes(String(body.action))) return json(400, { error: 'Unknown music action.' });
      const storefront = typeof body.storefront === 'string' ? body.storefront.toLowerCase() : '';
      if (!/^[a-z]{2}$/.test(storefront)) return json(400, { error: 'Choose a valid catalog country.' });
      const term = typeof body.term === 'string' ? body.term.trim() : '';
      const offset = body.offset === undefined ? 0 : body.offset;
      if (body.action === 'search' && (term.length < 2 || term.length > 120 || typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0 || offset > 980)) return json(400, { error: 'Enter 2 to 120 characters to search.' });
      const id = typeof body.id === 'string' ? body.id : '';
      if (body.action === 'track' && !/^\d{1,24}$/.test(id)) return json(400, { error: 'Invalid song.' });
      const url = new URL(body.action === 'search' ? `https://api.music.apple.com/v1/catalog/${storefront}/search` : `https://api.music.apple.com/v1/catalog/${storefront}/songs/${id}`);
      if (body.action === 'search') {
        url.searchParams.set('term', term); url.searchParams.set('types', 'songs');
        url.searchParams.set('limit', '20'); url.searchParams.set('offset', String(offset));
      }
      const { token } = await sign(credentials, undefined, now);
      const abort = new AbortController();
      const timer = setTimeout(() => abort.abort(), 10000);
      try {
        const response = await (deps.fetch || fetch)(url, { headers: { Authorization: `Bearer ${token}` }, signal: abort.signal });
        if (response.status === 404) return json(404, { error: 'This song or catalog is not available.' });
        if (response.status === 429) return json(429, { error: 'Apple Music is busy. Try again shortly.' });
        if (!response.ok) return json(503, { code: 'MUSIC_UNAVAILABLE', error: 'Apple Music could not be reached. Try again.' });
        const payload = await response.json();
        const songs = body.action === 'search' ? payload?.results?.songs : payload;
        const tracks = (Array.isArray(songs?.data) ? songs.data : []).map((row: unknown) => appleMusicTrackFromCatalog(row, storefront)).filter(Boolean);
        return json(200, { tracks, nextOffset: body.action === 'search' && songs?.next && Number(offset) < 980 ? Number(offset) + 20 : null });
      } finally { clearTimeout(timer); }
    } catch {
      return json(503, { code: 'MUSIC_UNAVAILABLE', error: 'Apple Music is temporarily unavailable. Try again.' });
    }
  };
}

import { serveBusinessRequest } from '../_shared/serveBusinessRequest.ts';
import { createClient } from 'npm:@supabase/supabase-js@2.112.3';
import { createAppleMusicHandler } from './handler.ts';

serveBusinessRequest(createAppleMusicHandler({
  env: name => Deno.env.get(name),
  authenticate: async request => {
    const authorization = request.headers.get('authorization');
    if (!authorization?.startsWith('Bearer ')) return null;
    const client = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_ANON_KEY')!, {
      global: { headers: { Authorization: authorization } },
      auth: { persistSession: false, autoRefreshToken: false },
    });
    const { data, error } = await client.auth.getUser();
    return error || !data.user ? null : { id: data.user.id, anonymous: data.user.is_anonymous };
  },
}));

export type MusicCredentials = { teamId: string; keyId: string; privateKey: string };

function encode(value: Uint8Array): string {
  let binary = '';
  for (const byte of value) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
}

/** ES256 signing remains on the server. A browser token is valid for one origin. */
export async function signMusicDeveloperToken(credentials: MusicCredentials, origin?: string, now = Date.now()) {
  const iat = Math.floor(now / 1000);
  const exp = iat + 600;
  const text = new TextEncoder();
  const header = encode(text.encode(JSON.stringify({ alg: 'ES256', kid: credentials.keyId })));
  const claims = encode(text.encode(JSON.stringify({ iss: credentials.teamId, iat, exp, ...(origin ? { origin: [origin] } : {}) })));
  const pem = credentials.privateKey.replace(/\\n/g, '\n').replace(/-----BEGIN PRIVATE KEY-----|-----END PRIVATE KEY-----|\s/g, '');
  const key = await crypto.subtle.importKey('pkcs8', Uint8Array.from(atob(pem), c => c.charCodeAt(0)), { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
  const body = `${header}.${claims}`;
  const signature = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, text.encode(body));
  return { token: `${body}.${encode(new Uint8Array(signature))}`, expiresAt: exp * 1000 };
}
